#include <stdio.h>
#include <math.h>



int main(void) {
    int n;
    double sum = 0;
    scanf("%d", &n);
    for (int i = 1; i <= n; i++) sum += 1.0 / ((double)i * i);
    printf("%.6f\n", sqrt(6 * sum));
    return 0;
}
